using Microsoft.Extensions.Logging.Abstractions;
using WAID.Application.Abstractions;
using WAID.Application.Services;
using WAID.Domain.Diagnostics;
using WAID.Domain.Repairs;

namespace WAID.Application.Tests;

public sealed class RepairOrchestrationTests
{
 [Fact]public void State_machine_rejects_invalid_transition()=>Assert.Throws<InvalidOperationException>(()=>RepairLifecycleStateMachine.EnsureTransition(RepairOrchestrationStage.Requested,RepairOrchestrationStage.Committed));
 [Fact]public async Task Assessment_and_simulation_make_no_changes_and_show_safeguards(){var f=new Fixture();var plan=await f.Orchestrator.AssessAndSimulateAsync(Request(),null,CancellationToken.None);Assert.Equal(RepairOrchestrationStage.AwaitingApproval,plan.Stage);Assert.False(f.Module.Executed);Assert.Equal(SafetyLevel.High,plan.Simulation!.Risk);Assert.Equal(RepairApprovalType.ExplicitHighRisk,plan.Simulation.SafetyAssessment!.RequiredApproval);Assert.True(plan.Simulation.RequiresBackup);Assert.Contains(plan.Simulation.Actions,x=>x.Contains("Registry",StringComparison.Ordinal));}
 [Fact]public async Task High_risk_execution_requires_separate_acknowledgement(){var f=new Fixture();var plan=await f.Orchestrator.AssessAndSimulateAsync(Request(),null,CancellationToken.None);var result=await f.Orchestrator.ExecuteAsync(plan.Id,true,false,null,CancellationToken.None);Assert.Equal(RepairOrchestrationStage.Cancelled,result.Stage);Assert.False(f.Module.Executed);Assert.False(result.Approval!.RiskAcknowledged);}
 [Fact]public async Task Successful_lifecycle_executes_validates_and_commits(){var f=new Fixture();var plan=await f.Orchestrator.AssessAndSimulateAsync(Request(),null,CancellationToken.None);var result=await f.Orchestrator.ExecuteAsync(plan.Id,true,true,null,CancellationToken.None);Assert.Equal(RepairOrchestrationStage.Committed,result.Stage);Assert.True(f.Module.Executed);Assert.True(result.Validation!.Succeeded);Assert.NotNull(result.BackupLocation);Assert.NotNull(result.RestorePointDescription);Assert.Equal(RepairTransactionStatus.Succeeded,result.TransactionStatus);}
 [Fact]public async Task Partial_execution_failure_is_rolled_back_and_reported(){var f=new Fixture();f.Module.Result=RepairResult.Failure("partial failure",actions:["step one completed"]);var plan=await f.Orchestrator.AssessAndSimulateAsync(Request(),null,CancellationToken.None);var result=await f.Orchestrator.ExecuteAsync(plan.Id,true,true,null,CancellationToken.None);Assert.Equal(RepairOrchestrationStage.RolledBack,result.Stage);Assert.Equal(1,f.Rollback.Count);Assert.Equal(RepairTransactionStatus.RolledBack,result.TransactionStatus);}
 [Fact]public async Task Validation_failure_never_reruns_and_requires_recovery(){var f=new Fixture();f.Validator.Succeed=false;var plan=await f.Orchestrator.AssessAndSimulateAsync(Request(),null,CancellationToken.None);var result=await f.Orchestrator.ExecuteAsync(plan.Id,true,true,null,CancellationToken.None);Assert.Equal(RepairOrchestrationStage.RecoveryRequired,result.Stage);Assert.Equal(1,f.Module.ExecutionCount);Assert.Contains("Do not rerun",result.Outcome,StringComparison.OrdinalIgnoreCase);}
 [Fact]public async Task Dependencies_and_conflicts_fail_before_approval(){var catalog=new Catalog(["required"],["conflict"]);var f=new Fixture(catalog:catalog);var result=await f.Orchestrator.AssessAndSimulateAsync(Request()with{ActiveRepairIds=new HashSet<string>(["conflict"],StringComparer.OrdinalIgnoreCase)},null,CancellationToken.None);Assert.Equal(RepairOrchestrationStage.Failed,result.Stage);Assert.False(f.Module.Executed);Assert.Contains("missing dependencies",result.Outcome,StringComparison.OrdinalIgnoreCase);}
 [Fact]public async Task Startup_recovery_cancels_pre_execution_and_flags_execution_uncertainty(){var f=new Fixture();var before=await f.Orchestrator.AssessAndSimulateAsync(Request(),null,CancellationToken.None);var execution=before with{Id=Guid.NewGuid(),Stage=RepairOrchestrationStage.Executing,Outcome="interrupted"};await f.Repository.SaveAsync(execution,CancellationToken.None);var recovered=await f.Orchestrator.RecoverInterruptedAsync(CancellationToken.None);Assert.Contains(recovered,x=>x.Id==before.Id&&x.Stage==RepairOrchestrationStage.Cancelled);Assert.Contains(recovered,x=>x.Id==execution.Id&&x.Stage==RepairOrchestrationStage.RecoveryRequired);Assert.False(f.Module.Executed);}
 [Fact]public async Task Concurrent_execution_is_rejected_and_cancelled_execution_rolls_back(){var f=new Fixture(block:true);var one=await f.Orchestrator.AssessAndSimulateAsync(Request(),null,CancellationToken.None);var two=await f.Orchestrator.AssessAndSimulateAsync(Request(),null,CancellationToken.None);using var cancellation=new CancellationTokenSource();var active=f.Orchestrator.ExecuteAsync(one.Id,true,true,null,cancellation.Token);await f.Module.Started.Task.WaitAsync(TimeSpan.FromSeconds(2));var error=await Assert.ThrowsAsync<RepairOrchestrationException>(()=>f.Orchestrator.ExecuteAsync(two.Id,true,true,null,CancellationToken.None));Assert.Equal("WAID-REPAIR-CONCURRENT",error.Code);cancellation.Cancel();await Assert.ThrowsAnyAsync<OperationCanceledException>(()=>active);Assert.Equal(1,f.Rollback.Count);Assert.Contains(f.History.Transactions,x=>x.Status==RepairTransactionStatus.RolledBack);}
 [Fact]public async Task Changed_plan_invalidates_simulation_and_cannot_execute(){var f=new Fixture();var plan=await f.Orchestrator.AssessAndSimulateAsync(Request(),null,CancellationToken.None);f.Module.ResourcePath=@"HKLM\Software\WAIDChanged";var result=await f.Orchestrator.ExecuteAsync(plan.Id,true,true,null,CancellationToken.None);Assert.Equal(RepairOrchestrationStage.Cancelled,result.Stage);Assert.False(f.Module.Executed);Assert.Contains("stale",result.Outcome,StringComparison.OrdinalIgnoreCase);}
 [Fact]public async Task Administrator_check_occurs_at_execution_not_simulation(){var f=new Fixture();f.Administrator.IsAdmin=false;var plan=await f.Orchestrator.AssessAndSimulateAsync(Request(),null,CancellationToken.None);Assert.Equal(RepairOrchestrationStage.AwaitingApproval,plan.Stage);var result=await f.Orchestrator.ExecuteAsync(plan.Id,true,true,null,CancellationToken.None);Assert.Equal(RepairOrchestrationStage.Failed,result.Stage);Assert.False(f.Module.Executed);Assert.Contains("Administrator",result.Outcome,StringComparison.OrdinalIgnoreCase);}
 private static RepairOrchestrationRequest Request()=>new("waid.test",null,new HashSet<string>(StringComparer.OrdinalIgnoreCase),new HashSet<string>(StringComparer.OrdinalIgnoreCase));
 private sealed class Fixture
 {
  public Fixture(bool block=false,IRepairDependencyCatalog? catalog=null){Module=new Module(block);var registry=new RepairRegistry([Module]);Executor=new(registry,Administrator,Restore,Backup,Rollback,History,TimeProvider.System,NullLogger<RepairExecutor>.Instance);Orchestrator=new(registry,Executor,Repository,Validator,catalog??new EmptyRepairDependencyCatalog(),TimeProvider.System,NullLogger<RepairOrchestrator>.Instance);}
  public Module Module{get;}public Admin Administrator{get;}=new();public Restore Restore{get;}=new();public Backup Backup{get;}=new();public Rollback Rollback{get;}=new();public History History{get;}=new();public Repository Repository{get;}=new();public Validator Validator{get;}=new();public RepairExecutor Executor{get;}public RepairOrchestrator Orchestrator{get;}
 }
 private sealed class Module(bool block):IRepairModule{public string Id=>"waid.test";public string DisplayName=>"Test";public string Description=>"Test repair";public RepairPolicy Policy{get;}=new(SafetyLevel.High);public bool Executed=>ExecutionCount>0;public int ExecutionCount;public RepairResult Result{get;set;}=RepairResult.Success("done");public string ResourcePath{get;set;}=@"HKLM\Software\WAID";public TaskCompletionSource Started{get;}=new(TaskCreationOptions.RunContinuationsAsynchronously);public Task<RepairPlan>CreatePlanAsync(DiagnosticFinding? f,CancellationToken t)=>Task.FromResult(new RepairPlan([new(RepairResourceKind.RegistryKey,ResourcePath)],Description));public async Task<RepairResult>ExecuteAsync(RepairExecutionContext c,CancellationToken t){Interlocked.Increment(ref ExecutionCount);Started.TrySetResult();if(block)await Task.Delay(Timeout.InfiniteTimeSpan,t);return Result;}}
 private sealed class Admin:IAdministratorService{public bool IsAdmin=true;public bool IsAdministrator()=>IsAdmin;}
 private sealed class Restore:IRestorePointManager{public Task<bool>IsAvailableAsync(CancellationToken t)=>Task.FromResult(true);public Task<RestorePointResult>CreateAsync(string d,CancellationToken t)=>Task.FromResult(new RestorePointResult(true,d));}
 private sealed class Backup:IBackupManager{public Task<BackupSnapshot>CreateAsync(Guid id,IReadOnlyCollection<RepairResource> r,CancellationToken t)=>Task.FromResult(new BackupSnapshot(@"C:\backup",r.Select(x=>new BackupItem(x,@"C:\backup\item")).ToArray(),[],Capability:RecoveryCapabilityLevel.ResourceBackup,IsValidated:true));}
 private sealed class Rollback:IRollbackManager{public int Count;public Task<RollbackResult>RollbackAsync(BackupSnapshot s,CancellationToken t){Count++;return Task.FromResult(new RollbackResult(true,["restored"],[],true,"verified"));}}
 private sealed class History:IRepairHistoryRepository{public List<RepairTransaction>Transactions{get;}=[];public Task SaveAsync(RepairTransaction x,CancellationToken t){Transactions.Add(x);return Task.CompletedTask;}public Task<IReadOnlyList<RepairHistoryEntry>>GetRecentAsync(int c,CancellationToken t)=>Task.FromResult<IReadOnlyList<RepairHistoryEntry>>([]);}
 private sealed class Repository:IRepairOrchestrationRepository{private readonly Dictionary<Guid,RepairOrchestrationRecord>_items=[];public Task SaveAsync(RepairOrchestrationRecord x,CancellationToken t){_items[x.Id]=x;return Task.CompletedTask;}public Task<RepairOrchestrationRecord?>GetAsync(Guid id,CancellationToken t)=>Task.FromResult(_items.GetValueOrDefault(id));public Task<IReadOnlyList<RepairOrchestrationRecord>>GetRecentAsync(int c,CancellationToken t)=>Task.FromResult<IReadOnlyList<RepairOrchestrationRecord>>(_items.Values.Take(c).ToArray());public Task<IReadOnlyList<RepairOrchestrationRecord>>GetNonTerminalAsync(CancellationToken t)=>Task.FromResult<IReadOnlyList<RepairOrchestrationRecord>>(_items.Values.Where(x=>x.Stage is not(RepairOrchestrationStage.Committed or RepairOrchestrationStage.RolledBack or RepairOrchestrationStage.Failed or RepairOrchestrationStage.Cancelled or RepairOrchestrationStage.RecoveryRequired)).ToArray());}
 private sealed class Validator:IRepairValidator{public string Version=>"test";public bool Succeed=true;public Task<RepairValidationOutcome>ValidateAsync(IRepairModule m,RepairTransaction x,CancellationToken t)=>Task.FromResult(new RepairValidationOutcome(Succeed,Version,DateTimeOffset.UtcNow,Succeed?"valid":"invalid",["test"]));}
 private sealed class Catalog(IReadOnlyList<string>d,IReadOnlyList<string>c):IRepairDependencyCatalog{public IReadOnlyList<string>DependenciesFor(string id)=>d;public IReadOnlyList<string>ConflictsFor(string id)=>c;}
}
